        setAskForEquipmentDetails(response.json.ask_for_equipment_details !== false);
      }
    }).catch(() => {});
    return () => { current = false; };
  }, [executionScope]));
  const [swapAccForm, setSwapAccForm] = useState({
    sets: '',
    rir: '',
  });
  const [swapRepTarget, setSwapRepTarget] = useState<AccessoryRepTarget>({ mode: 'FIXED', fixed: '10' });

  useEffect(() => {
    const itemId = Number(swapAccItem?.id || 0);
    if (!itemId || !acceptedSetEvidenceItemIds.has(itemId)) return;
    setSwapPickerVisible(false);
    setSwapAccVisible(false);
    setSwapAccItem(null);
    setSwapAccIdentity(null);
  }, [
    acceptedSetEvidenceItemIds,
    swapAccItem?.id,
  ]);

  const sessionMovementHistoryResolution = (item: WorkoutItem, athleteId: number) =>
    resolveMovementHistoryLaunchForItem({
      athleteId,
      item,
      includeEquipmentContext: askForEquipmentDetails
        && !isUnspecifiedEquipmentIdentity(activeEquipmentIdentity(item)),
    });

  const openCanonicalMovementHistory = (item: WorkoutItem) => {
    const resolution = sessionMovementHistoryResolution(item, Number(data?.workout?.athlete_id || 0));
    if (!resolution.ok) {
      if (__DEV__) console.warn('[MovementHistory] launch rejected', resolution.reason, item.id);
      Alert.alert('History unavailable', resolution.message);
      return;
    }
    router.push(movementHistorySheetRoute(resolution.target, { kind: 'session_logger', workoutId: Number(workoutId), athleteId: resolution.target.athleteId, mode: coachPreviewRequested ? 'preview' : 'execute', displayUnit: unit }) as never);
  };

  const openSwapAcc = (it: WorkoutItem) => {
    const currentWorkout = data?.workout;
    const authority = resolveSubstitutionAuthority({
      serverAuthority: data?.permissions?.substitution_authority,
      canHotSwap: data?.permissions?.can_hot_swap,
      permissionIsSelfCoached: data?.permissions?.is_self_coached,
      accountIsSelfCoached: user?.is_self_coached,
      isCoachPreview: coachPreviewRequested,
    });
    const swapAction = accessorySwapActionForItem({
      substitutionAuthority: authority,
      hasApprovedSubstitutions: approvedSubstitutionIdentities(it.approved_sub_identities).length > 0,
      isCoachPreview:
        coachPreviewRequested
        && data?.view_mode === 'coach_preview'
        && data?.permissions?.view_only === true,
      sessionLifecycle: deriveScreenMode(currentWorkout?.status),
      targetItemHasSetLogs: itemHasPersistedSetLogs(it),
      targetItemHasRemainingSets: nextMissingSetIndex(
        it.set_logs,
        positiveInt(accessoryExecutionItem(it).sets),
      ) != null,
      acceptedPersistedSetLogForItem: acceptedSetEvidenceItemIds.has(Number(it.id)),
    });
    if (!swapAction) return;
    education.markLearned('active-session-edit');
    setSwapError(null);
    setSwapAccItem(it);
    // The programmed/effective identity is context, never a selectable
    // replacement. A deliberate new governed identity is required.
    setSwapAccIdentity(null);
    setSwapAccForm({
      sets: (it.performed_sets ?? it.sets) != null ? String(it.performed_sets ?? it.sets) : '',
      rir: (it.performed_rir_target ?? it.rir_target) != null ? String(it.performed_rir_target ?? it.rir_target) : '',
    });
    setSwapRepTarget(accessoryRepTargetFromText(
      it.performed_reps_text || it.reps_text || (it.reps != null ? String(it.reps) : '10'),
    ));
    setSwapPickerVisible(true);
  };

  const resetSwapPrescription = () => {
    if (!swapAccItem) return;
    setSwapAccForm({
      sets: (swapAccItem.performed_sets ?? swapAccItem.sets) != null ? String(swapAccItem.performed_sets ?? swapAccItem.sets) : '',
      rir: (swapAccItem.performed_rir_target ?? swapAccItem.rir_target) != null ? String(swapAccItem.performed_rir_target ?? swapAccItem.rir_target) : '',
    });
    setSwapRepTarget(accessoryRepTargetFromText(
      swapAccItem.performed_reps_text || swapAccItem.reps_text || (swapAccItem.reps != null ? String(swapAccItem.reps) : '10'),
    ));
  };

  const swapPreviousPrescription = swapAccItem ? accessoryTargetLine(swapAccItem) : '';
  const swapReplacementPrescription = swapAccItem
    ? `${positiveInt(Number(swapAccForm.sets || 0))}×${accessoryRepTargetText(swapRepTarget) || '—'}${swapAccForm.rir === '' ? '' : ` @${swapAccForm.rir} RIR`}`
    : '';

  const saveSwapAcc = async () => {
    if (!workoutId || !swapAccItem || hotSwapGateRef.current.isWorking()) return;
    if (
      itemHasPersistedSetLogs(swapAccItem)
      || acceptedSetEvidenceItemIds.has(Number(swapAccItem.id))
    ) {
      setSwapPickerVisible(false);
      setSwapAccVisible(false);
      setSwapAccItem(null);
      setSwapAccIdentity(null);
      setError('This movement has saved Sets and can no longer be swapped.');
      return;
    }

    const setsStr = String(swapAccForm.sets || '').trim();
    const repsText = accessoryRepTargetText(swapRepTarget);
    const rirStr = String(swapAccForm.rir || '').trim();

    if (!swapAccIdentity?.id) {
      setSwapError('Select a movement.');
      return;
    }

    let sets: number | null = null;
    if (setsStr !== '') {
      const n = parseInt(setsStr.replace(/[^0-9]/g, ''), 10);
      if (!Number.isFinite(n) || n < 0) {
        setSwapError('Enter a valid number of Sets.');
        return;
      }
      sets = n;
    }

    let rir: number | null = null;
    if (rirStr !== '') {
      const cleaned = rirStr.replace(/[^0-9.\-]/g, '').replace(/(?!^)-/g, '');
      const n = parseFloat(cleaned);
      if (!Number.isFinite(n)) {
        setSwapError('Enter a valid RIR.');
        return;
      }
      rir = n;
    }

    const sameMovement = Number(swapAccItem.movement_definition_id) === Number(swapAccIdentity.id);
    const unchangedPrescription = substitutionAuthority !== 'self_governed' || (
      sets === (swapAccItem.performed_sets ?? swapAccItem.sets ?? null)
      && rir === (swapAccItem.performed_rir_target ?? swapAccItem.rir_target ?? null)
      && repsText === accessoryRepTargetText(accessoryRepTargetFromText(
        swapAccItem.performed_reps_text || swapAccItem.reps_text || (swapAccItem.reps != null ? String(swapAccItem.reps) : '10'),
      ))
    );
    if (sameMovement && unchangedPrescription) {
      // A same-ID selection has no write to reconcile, including on the old
      // TestFlight API whose Swap endpoint would reset selected equipment.
      setSwapPickerVisible(false);
      setSwapAccVisible(false);
      setSwapAccItem(null);
      setSwapAccIdentity(null);
      return;
    }

    const swapOwner = executionScope;
    if (!hotSwapGateRef.current.begin()) return;
    try {
      setSavingItemId(swapAccItem.id);
      setSwapError(null);
      // An older background read must not replace the authoritative mutation.
      workoutRequestManagerRef.current.cancel();
      const result = await executeActiveSessionHotSwap({
        sessionId: Number(workoutId),
        itemId: Number(swapAccItem.id),
        openedMovementId: Number(swapAccItem.movement_definition_id),
        replacementId: Number(swapAccIdentity.id),
        replacementName: swapAccIdentity.display_name || '',
        prescription: substitutionAuthority === 'self_governed'
          ? { sets, repsText, rir } : null,
        request: async (path, options) => fetchJson(`${API_BASE}${path}`, {
          ...options, auth: true,
        }),
        trace: __DEV__ ? (event) => console.info('[Session Hot Swap]', event) : undefined,
      });

      if (executionScopeRef.current !== swapOwner) return;
      let savedItem = result.item as WorkoutItem;
      const authoritativeSession = result.session as WorkoutPayload;
      const priorEquipment = swapAccItem.performed_movement_identity;
      if (!result.alreadyApplied && sameMovement && priorEquipment?.key?.startsWith('machine_equipment_')
        && Number(savedItem?.performed_movement_identity?.id) !== Number(priorEquipment.id)) {
        // Older APIs reset equipment when only the prescription changed.
        // Retain the athlete's explicit selection through their existing
        // equipment endpoint; the current API preserves it in the first write.
        const retained = await fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${swapAccItem.id}/performed-identity`, {
          method: 'PUT', auth: true, body: { movement_definition_id: priorEquipment.id },
        });
        if (!retained.ok || !retained.json?.ok
          || Number(retained.json.performed_movement_identity?.id) !== Number(priorEquipment.id)) {
          hotSwapGateRef.current.end();
          void fetchWorkout({ silent: true, reason: 'manual' });
          throw new Error('Prescription saved, but equipment could not be retained. Choose your equipment again before logging.');
        }
        if (executionScopeRef.current !== swapOwner) return;
        if (savedItem) savedItem = { ...savedItem, performed_movement_identity: retained.json.performed_movement_identity };
      }
      if (savedItem) {
        const projectSavedItem = (payload: WorkoutPayload | null) => payload ? {
          ...payload,
          workout: {
            ...payload.workout,
            accessory_groups: payload.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => Number(item.id) === Number(savedItem.id)
                ? { ...item, ...savedItem, set_logs: item.set_logs || [] }
                : item),
            })),
          },
        } : payload;
        // Start from the precondition GET, so all other Session rows are as
        // current as the server read used for this mutation.
        dataRef.current = projectSavedItem(authoritativeSession);
        setData(dataRef.current);
      }
      setSwapAccVisible(false);
      setSwapAccItem(null);
      rememberScroll();
      // The accepted response is projected synchronously. Reconciliation is
      // silent and must never launch equipment selection; that gate belongs
      // immediately before the first performed SetLog.
      hotSwapGateRef.current.end();
      void fetchWorkout({ silent: true, reason: 'manual' });
    } catch (err: any) {
      setSwapError(err?.message || 'Could not swap this movement. Try again.');
    } finally {
      hotSwapGateRef.current.end();
      setSavingItemId(null);
    }
  };

  const openEditSet = (
    itemId: number,
    setLog: SetLog,
    opts: { mode: 'rpe' | 'rir'; movementName: string }
  ) => {
    setError(null);
    const item = [...(data?.workout?.core_items || []), ...(data?.workout?.accessory_groups || []).flatMap(group => group.items)]
      .find(candidate => candidate.id === itemId);
    const revision = Number(item?.evidence_revision || 0);
    const retained = item && journalHydrated ? journal?.edit(setLog.id, journalIdentityForItem(item), revision) : null;
    if (journal?.hasEdit(setLog.id) && !retained) setError('This Set changed since your saved edit. Review its current values before saving.');
    const editedWeightKg = retained ? retained.weightKg : setLog.actual_weight_kg;
    const rawWeight =
      editedWeightKg != null
        ? unit === 'kg'
          ? formatWeight(editedWeightKg, 'kg')
          : String(roundToNearestGymIncrementLb(editedWeightKg / KG_PER_LB))
        : '';
    const weightOptions = buildEditWeightOptions(opts.mode, unit, rawWeight);
    const repsOptions = ['0', ...Array.from({ length: opts.mode === 'rpe' ? 20 : 30 }, (_, idx) => String(idx + 1))];
    const metricOptions = opts.mode === 'rpe'
      ? Array.from({ length: 11 }, (_, idx) => formatWheelNumber(5 + idx * 0.5))
      : Array.from({ length: 11 }, (_, idx) => formatWheelNumber(idx * 0.5));
    const rawMetric = retained ? (retained.effort.trim() ? Number(retained.effort) : null) : opts.mode === 'rpe' ? setLog.actual_rpe : setLog.actual_rir;

    setEditSetCtx({
      itemId,
      setIndex: setLog.set_index,
      setLogId: setLog.id,
      restoredDraft: !!retained,
      evidenceRevision: (() => {
        const item = [...(data?.workout?.core_items || []), ...(data?.workout?.accessory_groups || []).flatMap(group => group.items)]
          .find(candidate => candidate.id === itemId);
        const revision = Number((item as any)?.evidence_revision);
        return Number.isInteger(revision) && revision > 0 ? revision : null;
      })(),
      mode: opts.mode,
      movementName: opts.movementName,
      loggedWeightKg: setLog.actual_weight_kg ?? null,
      loggedReps: setLog.actual_reps ?? null,
      loggedRpe: setLog.actual_rpe ?? null,
      loggedRir: setLog.actual_rir ?? null,
    });

    setEditSetForm({
      weight: nearestWheelValue(weightOptions, rawWeight, weightOptions[0] || '0'),
      reps: nearestWheelValue(repsOptions, retained ? retained.reps : setLog.actual_reps != null ? String(setLog.actual_reps) : '', '0'),
      rpe: opts.mode === 'rpe'
        ? (isIndividualUser && rawMetric == null ? '' : nearestWheelValue(metricOptions, rawMetric != null ? formatWheelNumber(Number(rawMetric)) : '', '8'))
        : '',
      rir: opts.mode === 'rir'
        ? (isIndividualUser && rawMetric == null ? '' : nearestWheelValue(metricOptions, rawMetric != null ? formatWheelNumber(Number(rawMetric)) : '', '2'))
        : '',
    });

    setEditSetVisible(true);
  };

  const saveEditedSet = async () => {
    if (!workoutId || !editSetCtx || editSetInFlightRef.current) return;
    const ownerAtDispatch = executionScope;
    const assertEditOwner = () => {
      if (!screenMountedRef.current || executionScopeRef.current !== ownerAtDispatch) throw new Error('Session ownership changed.');
    };

    let weightInUnit =
      editSetForm.weight.trim() === '' ? NaN : parseFloat(editSetForm.weight);

    const repsStr = String(editSetForm.reps ?? '').replace(/[^0-9]/g, '');
    const reps = repsStr ? Number(repsStr) : NaN;

    // Zero is a performed load (for example, bodyweight with no added load),
    // not missing input. Match the canonical edit-set API's nonnegative rule.
    if (!Number.isFinite(weightInUnit) || weightInUnit < 0) {
      setError('Weight required');
      return;
    }
    if (!Number.isFinite(reps) || reps < 0) {
      setError('Reps required');
      return;
    }

    if (unit === 'lb') {
      weightInUnit = roundToNearestGymIncrementLb(weightInUnit);
    }

    const weightKg = unit === 'kg' ? weightInUnit : weightInUnit * KG_PER_LB;

    let actual_rpe: number | null = null;
    let actual_rir: number | null = null;

    if (editSetCtx.mode === 'rpe') {
      actual_rpe =
        editSetForm.rpe.trim() === '' ? null : parseFloat(editSetForm.rpe);
      if (editSetForm.rpe.trim() !== '' && !Number.isFinite(actual_rpe as number)) {
        setError('Enter a valid RPE');
        return;
      }
    } else {
      actual_rir =
        editSetForm.rir.trim() === '' ? null : parseFloat(editSetForm.rir);
      if (editSetForm.rir.trim() !== '' && !Number.isFinite(actual_rir as number)) {
        setError('Enter a valid RIR');
        return;
      }
    }

    try {
      editSetInFlightRef.current = true;
      assertEditOwner();
      setEditSetSubmitting(true);
      setSavingItemId(editSetCtx.itemId);
      setError(null);

      const isDevFixtureSet = isIdealWorkoutDetailPreview
        && data?.workout?.accessory_groups?.some((group) =>
          group.items.some((item) =>
            item.id === editSetCtx.itemId
            && (item.set_logs || []).some((log) => log.id === editSetCtx.setLogId),
          ),
        );
      if (isDevFixtureSet) {
        setData((current) => current ? {
          ...current,
          workout: {
            ...current.workout,
            accessory_groups: current.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => item.id !== editSetCtx.itemId
                ? item
                : {
                    ...item,
                    set_logs: (item.set_logs || []).map((log) =>
                      log.id !== editSetCtx.setLogId
                        ? log
                        : {
                            ...log,
                            actual_weight_kg: weightKg,
                            actual_reps: reps,
                            actual_rpe,
                            actual_rir,
                          }),
                  }),
            })),
          },
        } : current);
        feedbackDispatch({ type: 'SET_EDITED', sourceSetLogId: editSetCtx.setLogId });
        setEditSetVisible(false);
        setEditSetCtx(null);
        showSetMutationNotice('Set updated · progress recalculated');
        return;
      }

      const desired = { actual_weight_kg: weightKg, actual_reps: reps, actual_rpe, actual_rir };
      const body = Object.freeze({ ...desired, set_index: editSetCtx.setIndex, set_log_id: editSetCtx.setLogId,
        ...(editSetCtx.evidenceRevision != null ? { expected_evidence_revision: editSetCtx.evidenceRevision } : {}),
      });
      const json = await recoverSetEdit({
        workoutId: String(workoutId), itemId: editSetCtx.itemId, setLogId: editSetCtx.setLogId,
        desired, expectedRevision: editSetCtx.evidenceRevision, assertOwner: assertEditOwner,
        request: () => fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${editSetCtx.itemId}/edit_set`, {
          method: 'POST',
          auth: true,
          body,
        }),
      });
      assertEditOwner();

      void journal?.acceptedEdit(editSetCtx.setLogId).catch(() => undefined);
      feedbackDispatch({ type: 'SET_EDITED', sourceSetLogId: editSetCtx.setLogId });
      const invalidatedEventIds = Array.isArray(json?.invalidated_recognition_event_ids)
        ? json.invalidated_recognition_event_ids.map(Number).filter(Number.isFinite)
        : [];
      feedbackDispatch({ type: 'INVALIDATE_EVENTS', eventIds: invalidatedEventIds });
      if (workoutId) void invalidateRecognitionForSet(String(workoutId), editSetCtx.setLogId).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'edit', source_set_log_id: editSetCtx.setLogId }));
      if (workoutId) void invalidateRecognitionEvents(String(workoutId), invalidatedEventIds).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'edit', count: invalidatedEventIds.length }));
      feedbackAnalytics('recognition_invalidated_before_display', { source_set_log_id: editSetCtx.setLogId, mutation: 'edit' });

      setEditSetVisible(false);
      setData(current => applyConfirmedSetEdit(current, editSetCtx.itemId, editSetCtx.setLogId, json.set, json.item_evidence_revision));
      setEditSetCtx(null);
      rememberScroll();
      showSetMutationNotice('Set updated · progress recalculated');
      void fetchWorkout({ silent: true, reason: 'post_set' });
    } catch (err: any) {
      console.log('saveEditedSet error', err);
      if (screenMountedRef.current && executionScopeRef.current === ownerAtDispatch) {
        setError(isApiRequestError(err) && (err.kind === 'network' || err.kind === 'timeout')
          ? "Couldn't confirm this edit. Your changes are still here. Try again."
          : err?.message || 'Error updating set');
      }
    } finally {
      editSetInFlightRef.current = false;
      if (screenMountedRef.current && executionScopeRef.current === ownerAtDispatch) {
        setEditSetSubmitting(false);
        setSavingItemId(null);
      }
    }
  };

  const deleteSetLog = async (itemId: number, setLogId: number) => {
    if (!workoutId || !setLogId) return;

    try {
      setEditSetSubmitting(true);
      setSavingItemId(itemId);
      setError(null);

      const isDevFixtureSet = isIdealWorkoutDetailPreview
        && data?.workout?.accessory_groups?.some((group) =>
          group.items.some((item) =>
            item.id === itemId
            && (item.set_logs || []).some((log) => log.id === setLogId),
          ),
        );
      if (isDevFixtureSet) {
        setData((current) => current ? {
          ...current,
          workout: {
            ...current.workout,
            accessory_groups: current.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => item.id !== itemId
                ? item
                : {
                    ...item,
                    set_logs: (item.set_logs || []).filter(
                      (log) => log.id !== setLogId,
                    ),
                  }),
            })),
          },
        } : current);
        feedbackDispatch({ type: 'SET_DELETED', sourceSetLogId: setLogId });
        setEditSetVisible(false);
        setEditSetCtx(null);
        showSetMutationNotice('Set deleted · progress recalculated');
        return;
      }

      const { ok, status, json } = await fetchJson(
        `${API_BASE}/workouts/mobile/${workoutId}/setlogs/${setLogId}`,
        {
          method: 'DELETE',
          auth: true,
        }
      );

      if (!ok || !json?.ok) {
        throw new Error(json?.error || `Failed to delete set (HTTP ${status})`);
      }

      feedbackDispatch({ type: 'SET_DELETED', sourceSetLogId: setLogId });
      const invalidatedEventIds = Array.isArray(json?.invalidated_recognition_event_ids)
        ? json.invalidated_recognition_event_ids.map(Number).filter(Number.isFinite)
        : [];
      feedbackDispatch({ type: 'INVALIDATE_EVENTS', eventIds: invalidatedEventIds });
      if (workoutId) void invalidateRecognitionForSet(String(workoutId), setLogId).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'delete', source_set_log_id: setLogId }));
      if (workoutId) void invalidateRecognitionEvents(String(workoutId), invalidatedEventIds).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'delete', count: invalidatedEventIds.length }));
      feedbackAnalytics('recognition_invalidated_before_display', { source_set_log_id: setLogId, mutation: 'delete' });

      setEditSetVisible(false);
      setEditSetCtx(null);

      rememberScroll();
      await fetchWorkout();
      showSetMutationNotice('Set deleted · progress recalculated');
    } catch (err: any) {
      console.log('deleteSetLog error', err);
      setError(err?.message || 'Error deleting set');
    } finally {
      setEditSetSubmitting(false);
      setSavingItemId(null);
    }
  };

  const confirmDeleteSet = (itemId: number, log: SetLog) => {
    const metric = log.actual_rpe != null
      ? ` @ RPE ${formatWheelNumber(log.actual_rpe)}`
      : log.actual_rir != null
      ? ` @ ${formatWheelNumber(log.actual_rir)} RIR`
      : '';
    const weight = log.actual_weight_kg != null ? `${formatWeight(log.actual_weight_kg, unit)} ${unit}` : 'This set';
    const reps = log.actual_reps != null ? ` × ${log.actual_reps}` : '';
    Alert.alert(
      'Delete this set?',
      `${weight}${reps}${metric} will be removed from this training session. Any affected accomplishments and history will be recalculated.`,
      [
        { text: 'Keep Set', style: 'cancel' },
        { text: 'Delete Set', style: 'destructive', onPress: () => void deleteSetLog(itemId, log.id) },
      ],
    );
  };

  const openTimerPicker = useCallback((prescribedSeconds?: number, handoffIdentity?: string) => {
    if (coachPreviewRequested || dataRef.current?.workout?.status !== 'in_progress') return;
    if (typeof prescribedSeconds !== 'number') prescribedSeconds = undefined;
    const requestId = timerPickerOpenRequestRef.current + 1;
    timerPickerOpenRequestRef.current = requestId;
    const activeTimer = getRestTimerCompletionState().active;
    const activeTimerSeconds = !handoffIdentity && activeTimer?.workoutId === String(workoutId)
      && activeTimer.ownerUserId === restOwnerUserId ? deriveRestTimerRemainingSeconds(activeTimer, Date.now()) : null;

    const presentPicker = (lastUsedSeconds: number | null) => {
      if (timerPickerOpenRequestRef.current !== requestId) return;
      const initialSeconds = resolveRestTimerPickerInitialSeconds({
        activeTimerSeconds,
        sessionSelectedSeconds: sessionRestTimerSeconds,
        prescribedSeconds,
        lastUsedSeconds,
      });
      if (handoffIdentity) {
        activeTimerHandoffIdentityRef.current = handoffIdentity;
        timerHandoffReleaseControllerRef.current.begin(handoffIdentity, () => {
          activeTimerHandoffIdentityRef.current = null;
          feedbackDispatch({ type: 'TIMER_IDLE' });
        });
      }
      timerPickerChoiceRef.current = false;
      setTimerPickerValue(initialSeconds);
      setTimerPickerVisible(true);
      rewardLoopDemoV2Log('timer_handoff_opened', { default_seconds: initialSeconds });

      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          const idx = Math.max(0, REST_TIMER_OPTIONS_SECONDS.indexOf(initialSeconds));
          timerWheelRef.current?.scrollTo({
            y: idx * 44,
            animated: false,
          });
        });
      });
    };

    if (activeTimerSeconds || sessionRestTimerSeconds || prescribedSeconds) {
      presentPicker(null);
      return;
    }
    void loadScopedLastUsedRestTimer().then(presentPicker);
  }, [loadScopedLastUsedRestTimer, rewardLoopDemoV2Log, sessionRestTimerSeconds, coachPreviewRequested, workoutId, restOwnerUserId]);

  const startRestTimer = (seconds: number) => {
    if (executionScopeRef.current !== executionScope || coachPreviewRequested || !dataRef.current?.permissions?.can_log || dataRef.current?.workout.status !== 'in_progress') return;
    const endAt = Date.now() + seconds * 1000;
    const started = beginGlobalRestTimer({ workoutId, ownerUserId: restOwnerUserId, endAtMs: endAt });
    cancelRestEndNotification(started.replacedNotificationId);
    const timer = getRestTimerCompletionState().active;
    if (timer) void scheduleRestEndNotification(timer);
    feedbackDispatch({ type: 'TIMER_ACTIVE' });
  };

  const addRestTime = () => {
    if (executionScopeRef.current !== executionScope || coachPreviewRequested) return;
    const timer = getRestTimerCompletionState().active;
    if (timer?.workoutId !== String(workoutId) || timer.ownerUserId !== restOwnerUserId) return;
    const extended = extendGlobalRestTimer(timer.timerId, 30);
    if (!extended) return;
    cancelRestEndNotification(extended.replacedNotificationId);
    void scheduleRestEndNotification(extended.timer);
  };

  const confirmRestTimerSelection = (seconds: number) => {
    if (timerPickerChoiceRef.current || executionScopeRef.current !== executionScope || coachPreviewRequested) return;
    timerPickerChoiceRef.current = true;
    const normalizedSeconds = normalizeRestTimerSeconds(seconds);
    setSessionRestTimerSeconds(normalizedSeconds);
    if (restTimerPreferenceOwnerKey) {
      lastUsedRestTimerRef.current = {
        ownerKey: restTimerPreferenceOwnerKey,
        seconds: normalizedSeconds,
      };
      void persistLastUsedRestTimerSeconds(
        restTimerPreferenceOwnerKey,
        normalizedSeconds,
      ).catch((error) => console.warn('rest timer preference persistence failed', error));
    }
    startRestTimer(normalizedSeconds);
  };

  const stopRestTimer = () => {
    const snapshot = getRestTimerCompletionState();
    const timer = snapshot.active?.workoutId === String(workoutId) ? snapshot.active
      : snapshot.pending?.workoutId === String(workoutId) ? snapshot.pending : null;
    if (timer && timer.ownerUserId === restOwnerUserId && !coachPreviewRequested) {
      cancelRestEndNotification(timer.notificationId);
      void stopGlobalRestTimer(timer.timerId);
    }
    feedbackDispatch({ type: 'TIMER_IDLE' });
  };

  useEffect(() => {
    if (feedbackStateRef.current.timer.status !== 'picker_pending') {
      feedbackDispatch({ type: activeRestTimer ? 'TIMER_ACTIVE' : 'TIMER_IDLE' });
    }
  }, [activeRestTimer?.timerId, activeRestTimer?.endAtMs]);

  useEffect(() => {
    if (coachPreviewRequested || !workoutId || String(data?.workout?.status || '').toLowerCase() !== 'in_progress') return;
    void resumeSessionTiming(workoutId, data?.workout?.started_at).catch((error) => {
      console.warn('Session timing resume failed', error);
    });
  }, [data?.workout?.started_at, data?.workout?.status, workoutId, coachPreviewRequested]);

  useEffect(() => {
    const sub = AppState.addEventListener('change', (state) => {
      const previousState = loggerAppStateRef.current;
      loggerAppStateRef.current = state;
      if (state === 'active') feedbackDispatch({ type: 'APP_RESUMED' });
      else feedbackDispatch({ type: 'APP_BACKGROUNDED' });
      if (state === 'active' && previousState !== 'active') {
        resumeRefreshRef.current();
      }
      if (state === 'active') void reconcileGlobalRestTimerCompletion();
    });

    return () => sub.remove();
  }, [workoutId, coachPreviewRequested]);

  useEffect(() => {
    let cancelled = false;
    const status = String(data?.workout?.status || '').toLowerCase();
    if (coachPreviewRequested || !workoutId || status !== 'in_progress') return undefined;
    void hydrateRestTimerCompletion().then(() => reconcileGlobalRestTimerCompletion()).then(() => {
      if (cancelled) return;
      // The subscribed global deadline owns remount/foreground state.
    }).catch(() => undefined);
    return () => { cancelled = true; };
  }, [data?.workout?.status, workoutId, coachPreviewRequested]);

  useEffect(() => {
    if (coachPreviewRequested || !data?.workout || data.workout.status === 'in_progress') return;
    stopRestTimer();
    if (timerPickerVisible) resolveActiveTimerHandoff('dismissed');
  }, [data?.workout?.status, workoutId, coachPreviewRequested]);

  const updateStraightInput = (
    itemId: number,
    field: 'weight' | 'reps' | 'rpe',
    value: string,
  ) => {
    setStraightInputs((prev) => ({
      ...prev,
      [itemId]: {
        weight: prev[itemId]?.weight || '',
        reps: prev[itemId]?.reps || '',
        rpe: prev[itemId]?.rpe || '',
        [field]: value,
      },
    }));
  };

  const updateTopInput = (
    itemId: number,
    field: 'weight' | 'reps' | 'rpe',
    value: string,
  ) => {
    setTopInputs((prev) => ({
      ...prev,
      [itemId]: {
        weight: prev[itemId]?.weight || '',
        reps: prev[itemId]?.reps || '',
        rpe: prev[itemId]?.rpe || '',
        [field]: value,
      },
    }));
  };

  const updateBkInput = (
    itemId: number,
    field: 'weight' | 'reps' | 'rpe',
    value: string,
  ) => {
    setBkInputs((prev) => ({
      ...prev,
      [itemId]: {
        weight: prev[itemId]?.weight || '',
        reps: prev[itemId]?.reps || '',
        rpe: prev[itemId]?.rpe || '',
        [field]: value,
      },
    }));
  };

  const lastLogForItem = (item?: WorkoutItem | null) => {
    return latestRepeatableSet(item?.set_logs || []);
  };

  const prefillCoreInput = (
    kind: 'straight' | 'top' | 'bk',
    item: WorkoutItem,
    values: { weight?: string; reps?: string; rpe?: string },
  ) => {
    const apply = (prev: Record<number, { weight: string; reps: string; rpe: string }>) => {
      const cur = prev[item.id] || { weight: '', reps: '', rpe: '' };
      return {
        ...prev,
        [item.id]: {
          weight: values.weight ?? cur.weight,
          reps: values.reps ?? cur.reps,
          rpe: values.rpe ?? cur.rpe,
        },
      };
    };
    if (kind === 'straight') setStraightInputs(apply);
    if (kind === 'top') setTopInputs(apply);
    if (kind === 'bk') setBkInputs(apply);
  };

  const prefillFcInput = (
    key: string,
    values: { weight?: string; reps?: string; rpe?: string },
  ) => {
    setFcInputs((prev) => {
      const cur = prev[key] || { weight: '', reps: '', rpe: '' };
      return {
        ...prev,
        [key]: {
          weight: values.weight ?? cur.weight,
          reps: values.reps ?? cur.reps,
          rpe: values.rpe ?? cur.rpe,
        },
      };
    });
  };

  const loadIdentityPicker = useCallback(async (item: WorkoutItem) => {
    const entry = identityPickerEntryRef.current;
    if (!entry || entry.scope !== executionScopeRef.current) return;
    const requestId = ++identityPickerRequestRef.current;
    const currentRequest = () => requestId === identityPickerRequestRef.current
      && identityPickerEntryRef.current === entry && entry.scope === executionScopeRef.current;
    setIdentityPickerError(null);
    try { assertEquipmentFlowSubject(entry.subject, item); } catch (error: any) {
      setIdentityPickerError(error.message); setIdentityPickerRows([]); return;
    }
    const effective = resolveLoggerMovementIdentity(item).effective;
    const family = effective?.family_id;
    if (isIdealWorkoutDetailPreview) {
      const activeEquipment = activeEquipmentIdentity(item);
      const rows = orderEquipmentChoices(
        workoutDetailMachineIdentityChoices(
          '',
          family,
          effective?.family_display_name || entry.subject.displayName,
          entry.subject.movementDefinitionId,
        ) as GeneralMovementIdentity[],
        activeEquipment?.id,
      );
      if (currentRequest()) {
        setIdentityPickerRows(rows);
        setIdentityPickerLoading(false);
      }
      return;
    }
    setIdentityPickerLoading(true);
    try {
      const response = await fetchJson(
        `${API_BASE}/workouts/mobile/${workoutId}/items/${item.id}/equipment-manufacturers`,
        { method: 'GET', auth: true },
      );
      if (!response.ok || !response.json?.ok) throw new Error(response.json?.error || 'Could not load equipment choices.');
      if (!currentRequest()) return;
      assertEquipmentResponseSubject(entry.subject, response.json);
      setIdentityPickerRows(orderEquipmentChoices(
        response.json.items || [],
        activeEquipmentIdentity(item)?.id,
      ));
    } catch (error: any) {
      if (!currentRequest()) return;
      setIdentityPickerRows([]);
      setIdentityPickerError(error?.message || 'Could not load equipment choices.');
    } finally {
      if (currentRequest()) setIdentityPickerLoading(false);
    }
  }, [data?.athlete?.id, isIdealWorkoutDetailPreview, workoutId]);

  useEffect(() => {
    const entry = identityPickerEntryRef.current;
    if (!entry) return;
    const currentItem = data?.workout?.accessory_groups.flatMap(group => group.items)
      .find(item => Number(item.id) === entry.subject.itemId);
    try {
      if (entry.scope !== executionScope) throw new Error('Session context changed. Reopen Equipment from the current Session.');
      const subject = assertEquipmentFlowSubject(entry.subject, currentItem);
      setIdentityPickerSubject(subject);
      setIdentityPickerItem(currentItem || null);
    } catch (error: any) {
      identityPickerEntryRef.current = null;
      identityPickerRequestRef.current += 1;
      setIdentityPickerRows([]);
      setIdentityPickerManufacturer(null);
      setIdentityPickerLoading(false);
      setIdentityPickerError(error.message);
    }
  }, [data, executionScope]);

  useEffect(() => {
    if (!identityPickerItem) {
      identityPickerRequestRef.current += 1;
      return undefined;
    }
    void loadIdentityPicker(identityPickerItem);
    return undefined;
  }, [identityPickerItem, loadIdentityPicker]);

  const closeIdentityPicker = () => {
    identityPickerEntryRef.current = null;
    setIdentityPickerSubject(null);
    identityPickerRequestRef.current += 1;
    Keyboard.dismiss();
    setIdentityPickerItem(null);
    setIdentityPickerRows([]);
    setIdentityPickerError(null);
    setIdentityPickerContinuation({ kind: 'none' });
    setIdentityPickerManufacturer(null);
  };

  const resumeAfterEquipmentSelection = (
    nextItem: WorkoutItem,
    continuation: EquipmentSelectionContinuation,
    nextPayload?: WorkoutPayload | null,
  ) => {
    const continuationOwner = executionScope;
    if (continuation.kind === 'accessory_set') {
      requestAnimationFrame(() => { if (executionScopeRef.current === continuationOwner) openAccessoryWheel(nextItem, true); });
      return;
    }
    if (continuation.kind === 'group_round') {
      const source = nextPayload || data;
      const group = source?.workout?.accessory_groups?.find(
        (candidate) => candidate.group === continuation.groupLabel,
      );
      if (group) {
        requestAnimationFrame(() => {
          // Re-run the gate so tri-sets/giant sets can resolve the next
          // machine without discarding the round context.
          if (executionScopeRef.current === continuationOwner) openSupersetRoundLogger(group, continuation.roundIndex);
        });
      }
      return;
    }
  };

  const saveUnknownEquipment = async (
    item: WorkoutItem,
    continuation: EquipmentSelectionContinuation,
    automatic: boolean,
  ) => {
    if (!workoutId || unknownEquipmentSaveRef.current) return;
    const owner = executionScope;
    unknownEquipmentSaveRef.current = true;
    setIdentityPickerLoading(true);
    setIdentityPickerError(null);
    try {
      const response = await fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${item.id}/performed-identity`, {
        method: 'PUT', auth: true,
        body: { intent: 'skip_equipment', automatic_skip: automatic },
      });
      if (executionScopeRef.current !== owner) return;
      if (!response.ok || !response.json?.ok) throw new Error(response.json?.error || 'Could not skip equipment details.');
      const identity = response.json.performed_movement_identity as GeneralMovementIdentity;
      if (identity?.key !== 'machine_equipment_unknown_unknown' || identity.manufacturer?.key !== 'unknown') {
        throw new Error('The saved equipment could not be verified. Refresh the Session.');
      }
      const payload = dataRef.current;
      const nextItem = { ...item, performed_movement_identity: identity };
      if (payload) {
        const nextPayload = { ...payload, workout: { ...payload.workout,
          accessory_groups: payload.workout.accessory_groups.map(group => ({ ...group,
            items: group.items.map(candidate => Number(candidate.id) === Number(item.id) ? nextItem : candidate),
          })),
        }} as WorkoutPayload;
        dataRef.current = nextPayload;
        setData(nextPayload);
      }
      const refreshed = await fetchWorkout({ silent: true });
      if (executionScopeRef.current !== owner) return;
      if (!refreshed) throw new Error('Equipment was saved, but the Session could not refresh. Refresh before logging.');
      const confirmed = dataRef.current?.workout.accessory_groups.flatMap(group => group.items)
        .find(candidate => Number(candidate.id) === Number(item.id));
      if (confirmed?.performed_movement_identity?.id !== identity.id) {
        throw new Error('The saved equipment could not be confirmed. Refresh before logging.');
      }
      if (!automatic) closeIdentityPicker();
      const resume = () => resumeAfterEquipmentSelection(confirmed, continuation, dataRef.current);
      if (response.json.show_skip_preference_prompt) {
        Alert.alert('Stop asking for equipment details?',
          'Machine details can be skipped automatically. You can change this in Settings.', [
            { text: 'Keep Asking', onPress: resume },
            { text: "Don't Ask Again", onPress: () => {
              void fetchJson(`${API_BASE}/mobile/settings`, {
                method: 'PATCH', auth: true, body: { ask_for_equipment_details: false },
              }).then((saved) => {
                if (!saved.ok || !saved.json?.ok) throw new Error(saved.json?.error || 'Could not save preference.');
                setAskForEquipmentDetails(false);
              }).catch((error: any) => Alert.alert('Equipment setting not saved', error?.message || 'Please try again.'))
                .finally(resume);
            } },
          ]);
      } else resume();
    } catch (error: any) {
      if (automatic) Alert.alert('Equipment unavailable', error?.message || 'Please try again.');
      else setIdentityPickerError(error?.message || 'Could not skip equipment details.');
    } finally {
      unknownEquipmentSaveRef.current = false;
      setIdentityPickerLoading(false);
    }
  };

  const commitPerformedIdentity = async (
    identity: GeneralMovementIdentity,
    equipmentVariant?: MachineEquipmentType,
    expectedEquipmentId?: number,
  ) => {
    const entry = identityPickerEntryRef.current;
    if (!identityPickerItem || !workoutId || !entry || identityPickerSaveRef.current) return;
    const equipmentOwner = executionScope;
    const pickerItem = identityPickerItem;
    const continuation = identityPickerContinuation;
    const portableLoading = !equipmentVariant && identity.id === entry.subject.movementDefinitionId
      && entry.subject.allowsPortableLoading && continuation.kind !== 'evidence_correction';
    const previousIdentityId = activeEquipmentIdentity(pickerItem)?.id ?? null;
    identityPickerSaveRef.current = entry;
    setIdentityPickerLoading(true);
    try {
      const currentItem = dataRef.current?.workout?.accessory_groups.flatMap(group => group.items)
        .find(item => Number(item.id) === entry.subject.itemId);
      assertEquipmentFlowSubject(entry.subject, currentItem);
      assertEquipmentFlowSubject(entry.subject, pickerItem);
      if (entry.scope !== equipmentOwner) throw new Error('Session context changed. Reopen Equipment.');
      if (isIdealWorkoutDetailPreview) {
        const itemId = Number(pickerItem.id);
        const nextItem = applyWorkoutDetailMachineIdentity(
          pickerItem,
          Number(identity.id),
          identity,
        ) as WorkoutItem;
        const nextPayload = data ? {
          ...data,
          workout: {
            ...data.workout,
            accessory_groups: data.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => (
                Number(item.id) === itemId
                  ? nextItem
                  : item
              )),
            })),
          },
        } as WorkoutPayload : null;
        if (nextPayload) setData(nextPayload);
        rememberWorkoutDetailEquipmentSelection(workoutId, itemId, identity);
        closeIdentityPicker();
        setIdentityPickerLoading(false);
        if (previousIdentityId != null && Number(previousIdentityId) !== Number(identity.id)) {
          showSetMutationNotice('Equipment updated');
        }
        resumeAfterEquipmentSelection(nextItem, continuation, nextPayload);
        return;
      }
      const response = await fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${pickerItem.id}/performed-identity`, {
        method: 'PUT',
        auth: true,
        body: {
          ...(continuation.kind === 'evidence_correction' ? { intent: 'evidence_correction' } : {}),
          ...(portableLoading ? portableLoadingWrite(entry.subject)
            : equipmentFlowWrite(entry.subject, identity.manufacturer?.key || 'other', equipmentVariant)),
          ...(expectedEquipmentId ? { equipment_definition_id: expectedEquipmentId } : {}),
        },
      });
      if (executionScopeRef.current !== equipmentOwner || identityPickerEntryRef.current !== entry) return;
      if (!response.ok || !response.json?.ok) {
        setIdentityPickerError(response.json?.error || 'Could not save equipment choice.');
        setIdentityPickerLoading(false);
        return;
      }
      const latestPayload = dataRef.current;
      const latestItem = latestPayload?.workout.accessory_groups.flatMap(group => group.items)
        .find(item => Number(item.id) === entry.subject.itemId);
      assertEquipmentFlowSubject(entry.subject, latestItem);
      const nextItem = {
        ...latestItem!,
        performed_movement_identity:
          response.json?.performed_movement_identity,
      };
      if (portableLoading ? nextItem.performed_movement_identity?.id !== entry.subject.movementDefinitionId
        : !nextItem.performed_movement_identity?.key?.startsWith('machine_equipment_')) {
        throw new Error('The server did not return a supported equipment configuration. Refresh the Session.');
      }
      if (expectedEquipmentId && nextItem.performed_movement_identity?.id !== expectedEquipmentId) {
        throw new Error('Recent equipment changed. Reopen Equipment to refresh its history.');
      }
      assertEquipmentFlowSubject(entry.subject, nextItem);
      const nextPayload = latestPayload ? {
        ...latestPayload,
        workout: {
          ...latestPayload.workout,
          accessory_groups: latestPayload.workout.accessory_groups.map((group) => ({
            ...group,
            items: group.items.map((item) => (
              Number(item.id) === Number(nextItem.id)
                ? nextItem
                : item
            )),
          })),
        },
      } as WorkoutPayload : null;
      if (nextPayload) { dataRef.current = nextPayload; setData(nextPayload); }
      const refreshed = await fetchWorkout({ silent: true });
      if (executionScopeRef.current !== equipmentOwner || identityPickerEntryRef.current !== entry) return;
      if (!refreshed) throw new Error('Equipment was saved, but the Session could not refresh. Refresh before continuing to log.');
      const confirmedItem = dataRef.current?.workout.accessory_groups.flatMap(group => group.items)
        .find(item => Number(item.id) === entry.subject.itemId);
      assertEquipmentFlowSubject(entry.subject, confirmedItem);
      if (confirmedItem?.performed_movement_identity?.id !== nextItem.performed_movement_identity.id) {
        throw new Error('The saved equipment could not be confirmed. Refresh the Session before logging.');
      }
      if (expectedEquipmentId && confirmedItem.performed_movement_identity.id !== expectedEquipmentId) {
        throw new Error('Recent equipment changed. Reopen Equipment to refresh its history.');
      }
      closeIdentityPicker();
      setIdentityPickerLoading(false);
      if (previousIdentityId != null && Number(previousIdentityId) !== Number(identity.id)) {
        showSetMutationNotice('Equipment updated');
      }
      resumeAfterEquipmentSelection(confirmedItem!, continuation, dataRef.current || undefined);
    } catch (error: any) {
      if (identityPickerEntryRef.current === entry) setIdentityPickerError(error?.message || 'Could not save equipment choice.');
    } finally {
      if (identityPickerSaveRef.current === entry) identityPickerSaveRef.current = null;
      if (identityPickerEntryRef.current === entry) setIdentityPickerLoading(false);
    }
  };

  const choosePerformedIdentity = async (identity: GeneralMovementIdentity) => {
    if (identityPickerEntryRef.current?.subject.domain === 'cable') {
      Keyboard.dismiss();
      await commitPerformedIdentity(identity);
      return;
    }
    setIdentityPickerManufacturer(identity);
    setIdentityPickerQuery('');
    setIdentityPickerError(null);
    Keyboard.dismiss();
  };

  const chooseEquipmentVariant = async (
    variant: MachineEquipmentType,
  ) => {
    if (!identityPickerManufacturer) return;
    if (presentEquipmentHistory(identityPickerManufacturer, unit, false, variant).performance) education.markLearned('equipment-history');
    if (isIdealWorkoutDetailPreview) {
      const identity = workoutDetailMachineVariantIdentity(
        identityPickerManufacturer,
        variant,
      ) as GeneralMovementIdentity | null;
      if (!identity) {
        setIdentityPickerError('This equipment variant is unavailable.');
        return;
      }
      await commitPerformedIdentity(identity);
      return;
    }
    await commitPerformedIdentity(identityPickerManufacturer, variant);
  };

  const openIdentityPicker = (
    item: WorkoutItem,
    continuation: EquipmentSelectionContinuation = { kind: 'none' },
  ) => {
    let subject: EquipmentFlowSubject;
    try { subject = equipmentFlowSubject(item); } catch (error: any) {
      Alert.alert('Equipment unavailable', error.message); return;
    }
    const operation = continuation.kind === 'none'
      ? equipmentSelectionOperation({
          sessionStatus: data?.workout?.status,
          plannedSetCount: item.performed_sets ?? item.sets,
          loggedSetCount: (item.set_logs || []).length,
        })
      : 'configuration';
    const resolvedContinuation: EquipmentSelectionContinuation = (
      continuation.kind === 'none' && operation === 'evidence_correction'
        ? { kind: 'evidence_correction' }
        : continuation
    );
    const open = () => {
      if (executionScopeRef.current !== executionScope) return;
      try {
        const currentItem = dataRef.current?.workout?.accessory_groups.flatMap(group => group.items)
          .find(candidate => Number(candidate.id) === subject.itemId);
        subject = assertEquipmentFlowSubject(subject, currentItem);
        item = currentItem!;
      } catch (error: any) { Alert.alert('Equipment unavailable', error.message); return; }
      identityPickerRequestRef.current += 1;
      identityPickerEntryRef.current = { subject, scope: executionScope };
      setIdentityPickerSubject(subject);
      const effective = resolveLoggerMovementIdentity(item).effective;
      const initialRows = isIdealWorkoutDetailPreview
        ? orderEquipmentChoices(
            workoutDetailMachineIdentityChoices(
              '',
              effective?.family_id,
              effective?.family_display_name || subject.displayName,
              subject.movementDefinitionId,
            ) as GeneralMovementIdentity[],
            activeEquipmentIdentity(item)?.id,
          )
        : [];
      setIdentityPickerItem(item);
      setIdentityPickerQuery('');
      setIdentityPickerRows(initialRows);
      setIdentityPickerLoading(false);
      setIdentityPickerError(null);
      setIdentityPickerContinuation(resolvedContinuation);
      setIdentityPickerManufacturer(null);
    };
    if (
      continuation.kind === 'none'
      && operation === 'future_sets'
      && activeEquipmentIdentity(item)
    ) {
      Alert.alert(
        'Change equipment for upcoming sets?',
        'Sets already logged keep their original equipment identity. Your new choice applies only to future sets.',
        [{ text: 'Cancel', style: 'cancel' }, { text: 'Continue', onPress: open }],
      );
      return;
    }
    open();
  };

  const openAccessoryWheel = (item: WorkoutItem, skipEquipmentGate = false) => {
    if (!skipEquipmentGate && needsEquipmentSelection(item)) {
      if (!askForEquipmentDetails) {
        void saveUnknownEquipment(item, { kind: 'accessory_set', itemId: Number(item.id) }, true);
        return;
      }
      openIdentityPicker(
        item,
        {
          kind: 'accessory_set',
          itemId: Number(item.id),
        },
      );
      return;
    }
    const executionItem = accessoryExecutionItem(item);
    const idealRecommendationWeightKg = isIdealWorkoutDetailPreview
      ? Number((item as any).dev_accessory_intelligence?.recommendation_weight_kg)
      : NaN;
    const idealSuggestedWeight = Number.isFinite(idealRecommendationWeightKg) && idealRecommendationWeightKg > 0
      ? formatWeight(idealRecommendationWeightKg, unit)
      : '';
    const acceptedSet = acceptedLoadByItemIdRef.current[item.id] || null;
    const currentSetIndex = nextSetIndexFromEvidence([
      ...(item.set_logs || []),
      ...(acceptedSet ? [acceptedSet] : []),
    ]);
    const restoredDraft = journal?.draft(item.id, journalIdentityForItem(item), Number(item.evidence_revision || 1), currentSetIndex);
    const rawWeight = restoredDraft ? (restoredDraft.weightKg == null ? '' : displayWeightFromKg(restoredDraft.weightKg, unit)) : idealSuggestedWeight
      || defaultAccessoryWeight({ item: executionItem, unit, currentSetIndex, acceptedSet, allowFallback: !isIndividualUser });
    const weightOptions = buildAccessoryWeightOptions(unit, rawWeight);
    const repsOptions = ['0', ...Array.from({ length: 30 }, (_, idx) => String(idx + 1))];
    const rirOptions = Array.from({ length: 11 }, (_, idx) => formatWheelNumber(idx * 0.5));
    const repsDefault = restoredDraft?.reps || accInputs[item.id]?.reps || accessoryRepsDefault(executionItem);
    const rirDefault = restoredDraft?.effort || accInputs[item.id]?.rir || defaultAccessoryRir(executionItem);

    setAccessoryWheel({
      visible: true,
      itemId: item.id,
      setIndex: currentSetIndex,
      title: accessoryExecutionName(item),
      targetLine: accessoryTargetLine(executionItem),
      weight: !rawWeight && isIndividualUser ? '' : nearestWheelValue(weightOptions, rawWeight, '0'),
      reps: isIndividualUser && restoredDraft ? restoredDraft.reps : isIndividualUser && executionItem.reps == null && !executionItem.reps_text ? '' : nearestWheelValue(repsOptions, repsDefault, '10'),
      rir: isIndividualUser ? restoredDraft?.effort || '' : nearestWheelValue(rirOptions, rirDefault, '2'),
      weightOptions,
      repsOptions,
      rirOptions,
      selectedVideo: null,
    });
  };

  const queueAccessoryWheelLog = (wheel: AccessoryWheelState) => {
    const itemId = wheel.itemId;
    feedbackAnalytics('log_set_pressed', { item_id: itemId, movement_type: 'accessory' });
    setAccInputs((prev) => ({
      ...prev,
      [itemId]: {
        weight: wheel.weight,
        reps: wheel.reps,
        rir: wheel.reps === '0' ? '' : wheel.rir,
      },
    }));
    setPendingAccessoryLogItemId({
      itemId,
      setIndex: wheel.setIndex,
      selectedVideo: wheel.selectedVideo || null,
    });
  };

  const commitAccessoryWheel = () => {
    if (!accessoryWheel) return;
    queueAccessoryWheelLog(accessoryWheel);
  };

  const openSupersetRoundLogger = (
    group: AccessoryGroup,
    roundIndex: number,
  ) => {
    if (!group.group) return;
    const model = buildSupersetRoundModel(group.items);
    const round = model.rounds.find((candidate) => candidate.index === roundIndex);
    if (!round) return;

    const unresolvedIdentity = round.entries.find(
      ({ item, log }) =>
        !log
        && needsEquipmentSelection(item),
    );
    if (unresolvedIdentity) {
      if (!askForEquipmentDetails) {
        void saveUnknownEquipment(unresolvedIdentity.item, {
          kind: 'group_round', groupLabel: group.group, roundIndex,
        }, true);
        return;
      }
      openIdentityPicker(unresolvedIdentity.item, {
        kind: 'group_round',
        groupLabel: group.group,
        roundIndex,
      });
      return;
    }

    const entries = round.entries.map(({ item, log }) => {
        const restoredRoundDraft = !log ? journal?.draft(item.id, journalIdentityForItem(item), Number(item.evidence_revision || 1), roundIndex) : null;
        const executionItem = accessoryExecutionItem(item);
        const idealRecommendationWeightKg = Number(
          (item as any).dev_accessory_intelligence?.recommendation_weight_kg,
        );
        const suggestedWeight = Number.isFinite(idealRecommendationWeightKg)
          && idealRecommendationWeightKg > 0
          ? formatWeight(idealRecommendationWeightKg, unit)
          : '';
        const acceptedSet = acceptedLoadByItemIdRef.current[item.id] || null;
        const weight = log
          ? toWheelWeight(log as SetLog, unit)
          : suggestedWeight
            || defaultAccessoryWeight({
              item: executionItem,
              unit,
              currentSetIndex: roundIndex,
              acceptedSet,
            });
        const weightOptions = buildAccessoryWeightOptions(unit, weight || '0');
        const repsOptions = ['0', ...Array.from({ length: 30 }, (_, idx) => String(idx + 1))];
        const rirOptions = Array.from(
          { length: 11 },
          (_, idx) => formatWheelNumber(idx * 0.5),
        );
        const reps = log?.actual_reps != null
          ? String(log.actual_reps)
          : accInputs[item.id]?.reps || accessoryRepsDefault(executionItem);
        const rir = log?.actual_rir != null
          ? formatWheelNumber(Number(log.actual_rir))
          : accInputs[item.id]?.rir || defaultAccessoryRir(executionItem);
        const previousLog = latestRepeatableSet(
          (item.set_logs || []).filter(
            (candidate) => Number(candidate.set_index || 0) < roundIndex,
          ),
        );
        const repeatDraft = previousLog
          ? accessoryRepeatDraft(previousLog, toWheelWeight(previousLog, unit))
          : null;
        return {
          itemId: item.id,
          title: simplifyMobileMovementName(accessoryExecutionName(item)),
          prescription: accessoryTargetLine(executionItem),
          weight: restoredRoundDraft ? formatWeight(restoredRoundDraft.weightKg, unit) : nearestWheelValue(weightOptions, weight || '0', '0'),
          reps: restoredRoundDraft?.reps ?? nearestWheelValue(repsOptions, reps, '10'),
          rir: restoredRoundDraft?.effort ?? nearestWheelValue(rirOptions, rir, '2'),
          requiresRir: executionItem.rir_target != null,
          alreadyLogged: Boolean(log),
          loggedResult: log ? loggedSetText(log as SetLog, unit, item) : null,
          validationError: null,
          weightOptions,
          repsOptions,
          rirOptions,
          repeatLast: repeatDraft ? {
            weight: nearestWheelValue(weightOptions, repeatDraft.weight, '0'),
            reps: nearestWheelValue(repsOptions, repeatDraft.reps, '10'),
            rir: nearestWheelValue(rirOptions, repeatDraft.rir, '2'),
            preview: repeatSetPreview(previousLog as SetLog, {
              loadLabel: repeatLoadLabel(item, previousLog as SetLog, unit),
              effort: 'RIR',
            }),
          } : null,
        };
      });
    const draft = createSequentialGroupDraft(entries);
    supersetRoundSaveInFlightRef.current = false;
    resetSupersetRoundTransition();
    setError(null);
    setSupersetRoundLogger({
      groupLabel: group.group,
      roundIndex,
      roundCount: model.roundCount,
      activeIndex: draft.activeIndex,
      saving: false,
      entries: [...draft.entries],
    });
  };

  const updateSupersetRoundEntry = (
    itemId: number,
    field: 'weight' | 'reps' | 'rir',
    nextValue: string,
  ) => {
    setSupersetRoundLogger((current) => {
      if (!current) return current;
      const next = updateSequentialGroupDraft(
        {
          entries: current.entries,
          activeIndex: current.activeIndex,
        },
        itemId,
        field,
        String(nextValue || ''),
      );
      return {
        ...current,
        entries: [...next.entries],
        activeIndex: next.activeIndex,
      };
    });
  };

  const repeatLastIntoSupersetEntry = (itemId: number) => {
    if (
      supersetRoundSaveInFlightRef.current
      || supersetRoundTransitionInFlightRef.current
      || canonicalSetSubmissionControllerRef.current.isInFlight()
    ) return;
    void saveSupersetRound(itemId);
  };

  const resetSupersetRoundTransition = () => {
    supersetRoundTransitionTokenRef.current += 1;
    supersetRoundTransitionInFlightRef.current = false;
    supersetRoundStepOpacity.stopAnimation();
    supersetRoundStepTranslateX.stopAnimation();
    supersetRoundProgressFill.stopAnimation();
    supersetRoundCapturedPulse.stopAnimation();
    supersetRoundCapturedCueOpacity.stopAnimation();
    supersetRoundStepOpacity.setValue(1);
    supersetRoundStepTranslateX.setValue(0);
    supersetRoundProgressFill.setValue(1);
    supersetRoundCapturedPulse.setValue(0);
    supersetRoundCapturedCueOpacity.setValue(0);
    setSupersetRoundTransitioning(false);
    setSupersetRoundCapturedIndex(null);
    setSupersetRoundProgressIndex(null);
  };

  const runSupersetRoundStepTransition = (
    nextLogger: SupersetRoundLoggerState,
    direction: SequentialGroupTransitionDirection,
    capturedIndex: number | null,
  ) => {
    if (supersetRoundTransitionInFlightRef.current) return;
    const transition = sequentialGroupTransitionConfig(direction, reduceMotion);
    const transitionToken = supersetRoundTransitionTokenRef.current + 1;
    supersetRoundTransitionTokenRef.current = transitionToken;
    supersetRoundTransitionInFlightRef.current = true;
    setSupersetRoundTransitioning(true);
    setSupersetRoundCapturedIndex(capturedIndex);
    setSupersetRoundProgressIndex(direction === 'forward' ? nextLogger.activeIndex : null);
    setError(null);

    supersetRoundCapturedCueOpacity.setValue(0);
    supersetRoundCapturedPulse.setValue(0);
    if (direction === 'forward') {
      void Haptics.selectionAsync().catch(() => undefined);
      Animated.sequence([
        Animated.timing(supersetRoundCapturedCueOpacity, {
          duration: 60,
          easing: Easing.out(Easing.quad),
          toValue: 1,
          useNativeDriver: true,
        }),
        Animated.delay(90),
        Animated.timing(supersetRoundCapturedCueOpacity, {
          duration: 100,
          easing: Easing.in(Easing.quad),
          toValue: 0,
          useNativeDriver: true,
        }),
      ]).start();
      Animated.sequence([
        Animated.timing(supersetRoundCapturedPulse, {
          duration: 90,
          easing: Easing.out(Easing.quad),
          toValue: 1,
          useNativeDriver: true,
        }),
        Animated.timing(supersetRoundCapturedPulse, {
          duration: 120,
          easing: Easing.out(Easing.quad),
          toValue: 0,
          useNativeDriver: true,
        }),
      ]).start();
    }

    Animated.parallel([
      Animated.timing(supersetRoundStepOpacity, {
        duration: transition.outgoingDurationMs,
        easing: Easing.inOut(Easing.quad),
        toValue: 0.18,
        useNativeDriver: true,
      }),
      Animated.timing(supersetRoundStepTranslateX, {
        duration: transition.outgoingDurationMs,
        easing: Easing.inOut(Easing.quad),
        toValue: transition.outgoingTranslateX,
        useNativeDriver: true,
      }),
    ]).start(({ finished }) => {
      if (!finished || supersetRoundTransitionTokenRef.current !== transitionToken) return;
      supersetRoundStepOpacity.setValue(0);
      supersetRoundStepTranslateX.setValue(transition.incomingTranslateX);
      supersetRoundProgressFill.setValue(direction === 'forward' ? 0 : 1);
      setSupersetRoundLogger(nextLogger);

      requestAnimationFrame(() => {
        if (supersetRoundTransitionTokenRef.current !== transitionToken) return;
        Animated.parallel([
          Animated.timing(supersetRoundStepOpacity, {
            duration: transition.incomingDurationMs,
            easing: Easing.out(Easing.cubic),
            toValue: 1,
            useNativeDriver: true,
          }),
          Animated.timing(supersetRoundStepTranslateX, {
            duration: transition.incomingDurationMs,
            easing: Easing.out(Easing.cubic),
            toValue: 0,
            useNativeDriver: true,
          }),
          Animated.timing(supersetRoundProgressFill, {
            duration: transition.incomingDurationMs,
            easing: Easing.out(Easing.cubic),
            toValue: 1,
            useNativeDriver: true,
          }),
        ]).start(({ finished: incomingFinished }) => {
          if (
            !incomingFinished
            || supersetRoundTransitionTokenRef.current !== transitionToken
          ) return;
          supersetRoundTransitionInFlightRef.current = false;
          setSupersetRoundTransitioning(false);
          setSupersetRoundCapturedIndex(null);
          setSupersetRoundProgressIndex(null);
          AccessibilityInfo.announceForAccessibility(
            `Movement ${nextLogger.activeIndex + 1} of ${nextLogger.entries.length}`,
          );
        });
      });
    });
  };

  const advanceSupersetRoundLogger = () => {
    if (!supersetRoundLogger || supersetRoundTransitionInFlightRef.current) return;
    const result = advanceSequentialGroupStep({
      entries: supersetRoundLogger.entries,
      activeIndex: supersetRoundLogger.activeIndex,
    });
    setError(result.validation.message);
    if (!result.validation.valid) return;
    Keyboard.dismiss();
    runSupersetRoundStepTransition({
      ...supersetRoundLogger,
      entries: [...result.state.entries],
      activeIndex: result.state.activeIndex,
    }, 'forward', supersetRoundLogger.activeIndex);
  };

  const goBackInSupersetRoundLogger = () => {
    if (!supersetRoundLogger || supersetRoundTransitionInFlightRef.current) return;
    const previous = previousSequentialGroupStep({
      entries: supersetRoundLogger.entries,
      activeIndex: supersetRoundLogger.activeIndex,
    });
    setError(null);
    Keyboard.dismiss();
    runSupersetRoundStepTransition({
      ...supersetRoundLogger,
      entries: [...previous.entries],
      activeIndex: previous.activeIndex,
    }, 'backward', null);
  };

  const skipCurrentSupersetMovement = () => {
    if (!supersetRoundLogger || supersetRoundTransitionInFlightRef.current) return;
    const skipped = skipSequentialGroupStep({
      entries: supersetRoundLogger.entries,
      activeIndex: supersetRoundLogger.activeIndex,
    });
    setError(null);
    Keyboard.dismiss();
    const nextLogger = {
      ...supersetRoundLogger,
      entries: [...skipped.entries],
      activeIndex: skipped.activeIndex,
    };
    if (skipped.activeIndex !== supersetRoundLogger.activeIndex) {
      runSupersetRoundStepTransition(nextLogger, 'forward', null);
    } else {
      setSupersetRoundLogger(nextLogger);
    }
  };

  const logSupersetMovementIndividually = () => {
    if (!supersetRoundLogger || !data) return;
    const entry = supersetRoundLogger.entries[supersetRoundLogger.activeIndex];
    const group = data.workout.accessory_groups.find(
      (candidate) => candidate.group === supersetRoundLogger.groupLabel,
    );
    const item = group?.items.find((candidate) => candidate.id === entry?.itemId);
    if (!item) return;
    closeSupersetRoundLogger();
    requestAnimationFrame(() => openAccessoryWheel(item));
  };

  const closeSupersetRoundLogger = () => {
    supersetRoundSaveInFlightRef.current = false;
    resetSupersetRoundTransition();
    setError(null);
    setSupersetRoundLogger(null);
  };

  async function saveSupersetRound(repeatItemId?: number) {
    if (!supersetRoundLogger || !data || !workoutId) return;
    if (
      supersetRoundSaveInFlightRef.current
      || supersetRoundTransitionInFlightRef.current
      || supersetRoundLogger.saving
    ) return;
    let workingEntries = supersetRoundLogger.entries.map((entry) => (
      repeatItemId === entry.itemId && !entry.alreadyLogged && entry.repeatLast
        ? {
            ...entry,
            ...entry.repeatLast,
            skipped: false,
            validationError: null,
          }
        : entry
    ));
    if (repeatItemId != null) {
      const repeatEntry = workingEntries.find(
        (entry) => entry.itemId === repeatItemId && !entry.alreadyLogged && entry.repeatLast,
      );
      if (!repeatEntry) return;
    } else {
      const draftValidation = validateSequentialGroupForSave({
        entries: workingEntries,
        activeIndex: supersetRoundLogger.activeIndex,
      });
      if (!draftValidation.validation.valid) {
        setSupersetRoundLogger({
          ...supersetRoundLogger,
          entries: [...draftValidation.state.entries],
          activeIndex: draftValidation.state.activeIndex,
        });
        setError(draftValidation.validation.message);
        return;
      }
      workingEntries = [...draftValidation.state.entries];
    }

    const group = data.workout.accessory_groups.find(
      (candidate) => candidate.group === supersetRoundLogger.groupLabel,
    );
    if (!group) return;
    const model = buildSupersetRoundModel(group.items);
    const missingItemIds = new Set(
      missingSupersetRoundItemIds(model, supersetRoundLogger.roundIndex),
    );
    const skippedItemIds = repeatItemId != null
      ? [...missingItemIds].filter((itemId) => itemId !== repeatItemId)
      : workingEntries
          .filter((entry) => missingItemIds.has(entry.itemId) && entry.skipped)
          .map((entry) => entry.itemId);
    const parsedEntries: Array<Omit<SupersetRoundLoggerEntry, 'weight' | 'reps' | 'rir'> & {
      weight: number;
      weightKg: number;
      reps: number;
      rir: number | null;
    }> = [];
    for (const entry of workingEntries) {
      if (!missingItemIds.has(entry.itemId) || entry.skipped) continue;
      if (repeatItemId != null && entry.itemId !== repeatItemId) continue;
      let weight = entry.weight.trim() === '' ? 0 : Number(entry.weight);
      const reps = Number(String(entry.reps).replace(/[^0-9]/g, ''));
      const rirText = String(entry.rir).trim().replace(/[^0-9.\-]/g, '');
      const rir = rirText ? Number(rirText) : null;
      if (unit === 'lb') weight = roundToNearestGymIncrementLb(weight);
      parsedEntries.push({
        ...entry,
        weight,
        weightKg: unit === 'kg' ? weight : weight * KG_PER_LB,
        reps,
        rir,
      });
    }

    supersetRoundSaveInFlightRef.current = true;
    setSupersetRoundLogger({
      ...supersetRoundLogger,
      entries: workingEntries,
      saving: true,
    });
    try {
      if (!parsedEntries.length) {
        closeSupersetRoundLogger();
        return;
      }
      if (!isIdealWorkoutDetailPreview) {
        const roundIndex = supersetRoundLogger.roundIndex;
        const attemptKey = (
          `superset:${supersetRoundLogger.groupLabel}:${roundIndex}`
        );
        const canonicalPayload = {
          group: supersetRoundLogger.groupLabel,
          round_index: roundIndex,
          skipped_item_ids: skippedItemIds,
          entries: parsedEntries.map((entry) => ({
            item_id: entry.itemId,
            actual_weight_kg: entry.weightKg,
            actual_reps: entry.reps,
            actual_rir: entry.rir,
          })),
        };
        const roundSubmissionId = await submissionForAttempt(
          attemptKey,
          canonicalPayload,
        );
        const json = await submitCanonicalSet({
          itemId: parsedEntries[0].itemId,
          attemptKey,
          clientSubmissionId: roundSubmissionId,
          fallbackError: 'Could not save this round.',
          request: async () => {
            const response = await fetchJson(
              `${API_BASE}/workouts/mobile/${workoutId}/superset-rounds/${encodeURIComponent(supersetRoundLogger.groupLabel)}/${roundIndex}`,
              {
                method: 'POST',
                auth: true,
                body: {
                  skipped_item_ids: canonicalPayload.skipped_item_ids,
                  entries: canonicalPayload.entries.map((entry) => ({
                    ...entry,
                    client_submission_id:
                      `${roundSubmissionId}:${entry.item_id}`,
                    timing: createPerformedSetTiming(
                      Number(workoutId),
                      `${roundSubmissionId}:${entry.item_id}`,
                      prescribedRestSecondsForItem(entry.item_id),
                    ),
                  })),
                },
              },
            );
            if (!response.ok || !response.json?.ok) {
              throw new Error(
                response.json?.error
                || `Could not save this round (HTTP ${response.status})`,
              );
            }
            return response.json;
          },
        });
        if (!json) {
          supersetRoundSaveInFlightRef.current = false;
          setSupersetRoundLogger((current) => current ? {
            ...current,
            saving: false,
          } : current);
          return;
        }
        for (const entry of parsedEntries) {
          if (!entry.selectedVideo) continue;
          const accepted = (json.entries || []).find((result: any) => Number(result.item_id) === entry.itemId);
          const videoError = await attachSelectedVideoToLoggedSet(accepted?.set?.id, entry.selectedVideo);
          if (videoError) setError(videoError);
        }
        parsedEntries.forEach((entry) => {
          rememberAcceptedLoad(entry.itemId, roundIndex, entry.weightKg);
        });
        setAccInputs((current) => {
          const next = { ...current };
          parsedEntries.forEach((entry) => {
            next[entry.itemId] = {
              weight: formatWheelNumber(entry.weight),
              reps: '',
              rir: '',
            };
          });
          return next;
        });
        feedbackAnalytics('superset_round_logged', {
          group: supersetRoundLogger.groupLabel,
          round_index: roundIndex,
          movement_count: parsedEntries.length,
          persisted: true,
        });
        closeSupersetRoundLogger();
        await fetchWorkout({ silent: true, reason: 'post_set' });
        return;
      }
      const parsedByItemId = new Map(
        parsedEntries.map((entry) => [entry.itemId, entry]),
      );
      const roundIndex = supersetRoundLogger.roundIndex;
      setData((current) => current ? {
        ...current,
        workout: {
          ...current.workout,
          accessory_groups: current.workout.accessory_groups.map((candidate) => (
            candidate.group !== supersetRoundLogger.groupLabel
              ? candidate
              : {
                  ...candidate,
                  items: candidate.items.map((item) => {
                    const parsed = parsedByItemId.get(item.id);
                    const alreadyExists = (item.set_logs || []).some(
                      (log) => Number(log.set_index || 0) === roundIndex,
                    );
                    if (!parsed || alreadyExists) return item;
                    const mockSet: SetLog = {
                      id: 9_600_000 + (Number(item.id) * 10) + roundIndex,
                      set_index: roundIndex,
                      actual_weight_kg: parsed.weightKg,
                      actual_reps: parsed.reps,
                      actual_rpe: null,
                      actual_rir: parsed.rir,
                      client_submission_id:
                        `ideal-superset-${supersetRoundLogger.groupLabel}-${item.id}-${roundIndex}`,
                      ...equipmentSnapshotForSet(activeEquipmentIdentity(item)),
                    };
                    return {
                      ...item,
                      set_logs: [...(item.set_logs || []), mockSet],
                    };
                  }),
                }
          )),
        },
      } : current);
      setAccInputs((current) => {
        const next = { ...current };
        parsedEntries.forEach((entry) => {
          next[entry.itemId] = {
            weight: formatWheelNumber(entry.weight),
            reps: '',
            rir: '',
          };
        });
        return next;
      });
      feedbackAnalytics('superset_round_logged', {
        group: supersetRoundLogger.groupLabel,
        round_index: roundIndex,
        movement_count: parsedEntries.length,
      });
      closeSupersetRoundLogger();
      requestAnimationFrame(() => {
        openTimerPicker();
      });
    } catch (error: any) {
      supersetRoundSaveInFlightRef.current = false;
      setSupersetRoundLogger((current) => current ? {
        ...current,
        saving: false,
      } : current);
      setError(error?.message || 'Could not save this round.');
    }
  }

  const switchDisplayUnit = (nextUnit: 'kg' | 'lb') => {
    if (nextUnit === unit) return;
    const currentUnit = unit;
    unitLocalOverrideRef.current = nextUnit;

    setCoreWheel((prev) => {
      if (!prev) return prev;
      const weightKg = weightDisplayToKg(prev.weight, currentUnit);
      const nextWeightRaw = prev.weight.trim() ? displayWeightFromKg(weightKg, nextUnit) : '';
      const weightOptions = buildCoreWeightOptions(nextUnit, nextWeightRaw);
      return {
        ...prev,
        targetLine: convertLoggerPrescriptionUnit(prev.targetLine, nextUnit),
        prescriptionLine: convertLoggerPrescriptionUnit(prev.prescriptionLine, nextUnit),
        subtitle: nextUnit.toUpperCase(),
        weightOptions,
        weight: !nextWeightRaw && isIndividualUser ? '' : nearestWheelValue(weightOptions, nextWeightRaw, weightOptions[0] || (nextUnit === 'kg' ? '100' : '225')),
      };
    });

    setAccessoryWheel((prev) => {
      if (!prev) return prev;
      const weightKg = weightDisplayToKg(prev.weight, currentUnit);
      const nextWeightRaw = prev.weight.trim() ? displayWeightFromKg(weightKg, nextUnit) : '';
      const weightOptions = buildAccessoryWeightOptions(nextUnit, nextWeightRaw);
      return {
        ...prev,
        weightOptions,
        weight: !nextWeightRaw && isIndividualUser ? '' : nearestWheelValue(weightOptions, nextWeightRaw, '0'),
      };
    });

    setSupersetRoundLogger((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        entries: prev.entries.map((entry) => {
          const weightKg = weightDisplayToKg(entry.weight, currentUnit);
          const nextWeight = displayWeightFromKg(weightKg, nextUnit);
          const weightOptions = buildAccessoryWeightOptions(nextUnit, nextWeight);
          return {
            ...entry,
            weightOptions,
            weight: nearestWheelValue(weightOptions, nextWeight, '0'),
          };
        }),
      };
    });

    setEditSetForm((prev) => {
      if (!editSetVisible || !editSetCtx) return prev;
      const weightKg = weightDisplayToKg(prev.weight, currentUnit);
      const nextWeightRaw = displayWeightFromKg(weightKg, nextUnit);
      const weightOptions = buildEditWeightOptions(editSetCtx.mode, nextUnit, nextWeightRaw);
      return {
        ...prev,
        weight: nearestWheelValue(weightOptions, nextWeightRaw, weightOptions[0] || '0'),
      };
    });

    setUnit(nextUnit);
  };

  const openCoreWheel = ({
    kind,
    item,
    setIndex,
    planned,
    targetLine,
  }: {
    kind: CoreWheelKind;
    item: WorkoutItem;
    setIndex?: number;
    planned?: PlannedSet | null;
    targetLine?: string | null;
  }) => {
    const acceptedSet = acceptedLoadByItemIdRef.current[item.id] || null;
    const sessionEvidence = [
      ...(item.set_logs || []),
      ...(acceptedSet ? [acceptedSet] : []),
    ];
    const requestedSetIndex = Number(setIndex || 0);
    const requestedSetAlreadyLogged = requestedSetIndex > 0 && sessionEvidence.some(
      (set) => Number(set.set_index || 0) === requestedSetIndex,
    );
    const currentSetIndex = requestedSetIndex > 0 && !requestedSetAlreadyLogged
      ? requestedSetIndex
      : nextSetIndexFromEvidence(sessionEvidence);
    const restoredDraft = journal?.draft(item.id, journalIdentityForItem(item), Number(item.evidence_revision || 1), currentSetIndex);
    const rawWeight = restoredDraft ? (restoredDraft.weightKg == null ? '' : displayWeightFromKg(restoredDraft.weightKg, unit)) : defaultCoreWeight({
      item,
      unit,
      currentSetIndex,
      acceptedSet,
      planned: planned || null,
      allowFallback: !isIndividualUser,
    });
    const weightOptions = buildCoreWeightOptions(unit, rawWeight);
    const weight = !rawWeight && isIndividualUser ? '' : nearestWheelValue(weightOptions, rawWeight, weightOptions[0] || (unit === 'kg' ? '100' : '225'));
    const repsOptions = ['0', ...Array.from({ length: 20 }, (_, idx) => String(idx + 1))];
    const rpeOptions = Array.from({ length: 11 }, (_, idx) => formatWheelNumber(5 + idx * 0.5));
    const defaultReps = restoredDraft?.reps || defaultCoreReps(item, planned || null);
    const defaultRpe = restoredDraft?.effort || defaultCoreRpe(item, planned || null);
    const reps = isIndividualUser && restoredDraft ? restoredDraft.reps : isIndividualUser && item.reps == null && !planned?.reps
      ? '' : nearestWheelValue(repsOptions, defaultReps, defaultReps);
    const rpe = isIndividualUser ? restoredDraft?.effort || '' : nearestWheelValue(rpeOptions, defaultRpe, '8');

    setCoreWheel({
      visible: true,
      kind,
      itemId: item.id,
      setIndex: currentSetIndex,
      title: `${resolveLoggerMovementIdentity(item).displayName} · Set ${currentSetIndex}`,
      subtitle: unit.toUpperCase(),
      targetLine,
      prescriptionLine: targetLine ? [targetLine, reps ? `× ${reps}` : null, rpe ? `@${rpe}` : null].filter(Boolean).join(' ') : null,
      weight,
      reps,
      rpe,
      weightOptions,
      repsOptions,
      rpeOptions,
    });
  };

  const queueCoreWheelLog = (wheel: CoreWheelState) => {
    const weight = wheel.weight;
    feedbackAnalytics('log_set_pressed', { item_id: wheel.itemId, movement_type: 'core', set_kind: wheel.kind });
    const reps = wheel.reps;
    const rpe = reps === '0' ? '' : wheel.rpe;

    if (wheel.kind === 'straight') {
      prefillCoreInput('straight', { id: wheel.itemId } as WorkoutItem, { weight, reps, rpe });
    } else if (wheel.kind === 'top') {
      prefillCoreInput('top', { id: wheel.itemId } as WorkoutItem, { weight, reps, rpe });
    } else if (wheel.kind === 'bk') {
      prefillCoreInput('bk', { id: wheel.itemId } as WorkoutItem, { weight, reps, rpe });
    } else {
      prefillFcInput(`${wheel.itemId}:${wheel.setIndex}`, { weight, reps, rpe });
    }

    setPendingCoreWheelLog({
      selectedVideo: wheel.selectedVideo || null,
      kind: wheel.kind,
      itemId: wheel.itemId,
      setIndex: wheel.setIndex,
